module Ballast.Analysis.CSharpExtractor

open System
open System.Collections.Generic
open Microsoft.CodeAnalysis
open Microsoft.CodeAnalysis.CSharp.Syntax
open Ballast.Core

let private pathSegments (path: string) = path.Split([| '\\'; '/' |])

/// Source generator output, files under obj such as GlobalUsings.g.cs, and files marked auto-generated.
let private isGenerated (tree: SyntaxTree) =
    let inObj = pathSegments tree.FilePath |> Array.exists (fun part -> part.Equals("obj", StringComparison.OrdinalIgnoreCase))

    let marked =
        tree.GetRoot().GetLeadingTrivia()
        |> Seq.exists (fun trivia -> trivia.ToString().Contains "<auto-generated")

    inObj || marked

/// Namespace and containing types by metadata name, or "global" when there are none, as FCS spells it.
let private keyOf (symbol: INamedTypeSymbol) =
    let symbol = symbol.OriginalDefinition

    let rec containers (current: INamedTypeSymbol) =
        match current.ContainingType with
        | null -> []
        | outer -> containers outer @ [ outer.MetadataName ]

    let space =
        if symbol.ContainingNamespace.IsGlobalNamespace then [] else [ symbol.ContainingNamespace.ToDisplayString() ]

    { Assembly = symbol.ContainingAssembly.Name
      Path =
        match space @ containers symbol with
        | [] -> "global"
        | parts -> String.concat "." parts
      Name = symbol.MetadataName }

/// The outermost static class around a type, or the type itself when it is static, as a module path.
let private modulePathOf (symbol: INamedTypeSymbol) =
    let rec chain (current: INamedTypeSymbol) =
        match current with
        | null -> []
        | _ -> chain current.ContainingType @ [ current ]

    chain symbol
    |> List.tryFindIndex (fun t -> t.IsStatic)
    |> Option.map (fun index ->
        let names = chain symbol |> List.take (index + 1) |> List.map (fun t -> t.Name)

        let space =
            if symbol.ContainingNamespace.IsGlobalNamespace then [] else [ symbol.ContainingNamespace.ToDisplayString() ]

        String.concat "." (space @ names))

/// A record whose positional parameters, at least one, are all delegates, such as Func or Action.
let private isFunctionRecord (symbol: INamedTypeSymbol) =
    let positional =
        symbol.DeclaringSyntaxReferences
        |> Seq.tryPick (fun reference ->
            match reference.GetSyntax() with
            | :? RecordDeclarationSyntax as record when not (isNull record.ParameterList) ->
                Some(record.ParameterList.Parameters |> Seq.map (fun p -> p.Identifier.ValueText) |> List.ofSeq)
            | _ -> None)

    // The primary constructor is the one whose parameters carry the positional names.
    match positional with
    | Some names when symbol.IsRecord && not names.IsEmpty ->
        symbol.InstanceConstructors
        |> Seq.tryFind (fun c -> c.Parameters |> Seq.map (fun p -> p.Name) |> List.ofSeq = names)
        |> Option.exists (fun c -> c.Parameters |> Seq.forall (fun p -> p.Type.TypeKind = TypeKind.Delegate))
    | _ -> false

let private hasOwnMembers (symbol: INamedTypeSymbol) =
    symbol.GetMembers() |> Seq.exists (fun m -> not (m :? INamedTypeSymbol) && not m.IsImplicitlyDeclared)

/// The abstraction under the functional profile and the classic profile, mirroring the F# rules.
let private abstractionsOf (symbol: INamedTypeSymbol) =
    if symbol.TypeKind = TypeKind.Interface then
        Abstract, Abstract
    elif symbol.TypeKind = TypeKind.Class && symbol.IsAbstract && not symbol.IsStatic then
        Abstract, Abstract
    elif symbol.TypeKind = TypeKind.Delegate || isFunctionRecord symbol then
        Abstract, Concrete
    elif symbol.IsStatic && not (hasOwnMembers symbol) then
        NotCounted, NotCounted
    else
        Concrete, Concrete

let private declare project (symbol: INamedTypeSymbol) : Declaration =
    let functional, classic = abstractionsOf symbol

    { Key = keyOf symbol
      Project = project
      NamespacePath =
        if symbol.ContainingNamespace.IsGlobalNamespace then
            "<global>"
        else
            symbol.ContainingNamespace.ToDisplayString()
      ModulePath = modulePathOf symbol
      FunctionalAbstraction = functional
      ClassicAbstraction = classic
      IsData = symbol.IsRecord || symbol.TypeKind = TypeKind.Enum }

/// The reference packs and FSharp.Core, which never count as dependencies.
let private isFramework (compilation: Compilation) (symbol: INamedTypeSymbol) =
    let inReferencePack =
        match compilation.GetMetadataReference symbol.ContainingAssembly with
        | :? PortableExecutableReference as reference when not (isNull reference.FilePath) ->
            pathSegments reference.FilePath |> Array.contains "packs"
        | _ -> false

    symbol.ContainingAssembly.Name = "FSharp.Core" || inReferencePack

/// Named types in a type, through generic arguments, arrays and pointers. Type parameters and dynamic have none.
let rec private namedTypesIn (typeSymbol: ITypeSymbol) : INamedTypeSymbol list =
    match typeSymbol with
    | :? INamedTypeSymbol as named when named.TypeKind <> TypeKind.Error ->
        named.OriginalDefinition :: (named.TypeArguments |> Seq.collect namedTypesIn |> Seq.toList)
    | :? IArrayTypeSymbol as array -> namedTypesIn array.ElementType
    | :? IPointerTypeSymbol as pointer -> namedTypesIn pointer.PointedAtType
    | _ -> []

let private targetsOfSymbol (symbol: ISymbol) : INamedTypeSymbol list =
    match symbol with
    | :? INamedTypeSymbol as named -> namedTypesIn named
    | :? IMethodSymbol as method when method.MethodKind = MethodKind.LocalFunction || method.MethodKind = MethodKind.AnonymousFunction -> []
    | :? IMethodSymbol as method -> [ (if isNull method.ReducedFrom then method else method.ReducedFrom).ContainingType ]
    | :? IPropertySymbol
    | :? IFieldSymbol
    | :? IEventSymbol -> [ symbol.ContainingType ]
    | :? IAliasSymbol as alias -> (match alias.Target with :? INamedTypeSymbol as named -> namedTypesIn named | _ -> [])
    | _ -> []

/// Locals and parameters whose types may never be named in the source, such as var and lambda parameters.
let private declaredTypes (model: SemanticModel) (node: SyntaxNode) : INamedTypeSymbol list =
    match node with
    | :? VariableDeclaratorSyntax
    | :? ParameterSyntax
    | :? SingleVariableDesignationSyntax
    | :? ForEachStatementSyntax
    | :? CatchDeclarationSyntax ->
        match model.GetDeclaredSymbol node with
        | :? ILocalSymbol as local -> namedTypesIn local.Type
        | :? IParameterSymbol as parameter -> namedTypesIn parameter.Type
        | _ -> []
    | _ -> []

let private extractCompilation (compilation: Compilation) =
    let project = compilation.AssemblyName
    // Keyed by declaration key, so the parts of a partial type count once.
    let declared = Dictionary<DeclarationKey, INamedTypeSymbol>()
    let addDeclared (symbol: INamedTypeSymbol) = declared[keyOf symbol] <- symbol
    let edges = ResizeArray<Edge>()

    for tree in compilation.SyntaxTrees |> Seq.filter (isGenerated >> not) do
        let model = compilation.GetSemanticModel tree
        let root = tree.GetRoot()

        // Top-level statements belong to the synthesised Program class.
        let program =
            match model.GetDeclaredSymbol root with
            | :? IMethodSymbol as entryPoint -> Some entryPoint.ContainingType
            | _ -> None

        let sourceOf (node: SyntaxNode) =
            let declaration =
                node.AncestorsAndSelf()
                |> Seq.tryFind (fun n -> n :? BaseTypeDeclarationSyntax || n :? DelegateDeclarationSyntax)

            match declaration with
            | Some declaration ->
                match model.GetDeclaredSymbol declaration with
                | :? INamedTypeSymbol as symbol -> Some symbol
                | _ -> None
            | None when node.Ancestors() |> Seq.exists (fun n -> n :? GlobalStatementSyntax) -> program
            | None -> None

        program |> Option.iter addDeclared

        for node in root.DescendantNodes() do
            match node with
            | :? BaseTypeDeclarationSyntax
            | :? DelegateDeclarationSyntax ->
                match model.GetDeclaredSymbol node with
                | :? INamedTypeSymbol as symbol -> addDeclared symbol
                | _ -> ()
            | _ -> ()

            // using directives are not dependencies, as F# open declarations are not.
            if not (node.AncestorsAndSelf() |> Seq.exists (fun n -> n :? UsingDirectiveSyntax)) then
                match sourceOf node with
                | Some source ->
                    let symbol = model.GetSymbolInfo(node).Symbol

                    let targets =
                        (if isNull symbol then [] else targetsOfSymbol symbol) @ declaredTypes model node

                    for target in targets |> List.filter (isFramework compilation >> not) do
                        edges.Add { From = keyOf source; To = keyOf target }
                | None -> ()

    declared.Values |> Seq.map (declare project) |> Seq.toList, List.ofSeq edges

let extract (compilations: Compilation list) : Extraction =
    let extracted = compilations |> List.map extractCompilation

    { Declarations = extracted |> List.collect fst
      Edges = extracted |> List.collect snd |> List.distinct }
